ingen van een onervaren jongeman met een politieke omgeving waarin belangen en persoonlijke verhoudingen voortdurend door elkaar lopen.","work_id":987146002,"evidence":[{"note":"Retain existing Work1540 La chartreuse de Parme / Stendhal and exact Dutch De Chartreuse van Parma 9789023408192 Paperback. KB original-title/volume and existing source-edition parent compared; original content review content-review-025.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p822785129"],"reference":"work:1540","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-025.json","sources":["https://openlibrary.org/works/OL733285W","https://data.bibliotheken.nl/id/nbt/p822785129"]},{"note":"Exact bound bulk source attempt retained. No image claimedverifiedorimported; preserve current resolver. Require decodedexactfront or documentedneutralplaceholder in hostedacceptance; noEnglishsubstitution.","type":"no_verified_cover_asset_retained","isbn13":"9789023408192","status":"no_verified_asset_retained","attempts":[{"status":"bulk_archive_unavailable","coverId":7314000,"receipt":"cover-archive-v2-readback.json","receiptSha256":"4d3654aabbd278b441113fd2849c2921b159283130e3ff174337511c4b78ce11"}],"checkedAt":"2026-11-03T09:26:38.922Z","editionKey":"/books/OL25644058M","limitation":"No verified image is imported. Existing neutral placeholder; not proof that no cover exists at the provider or elsewhere."}],"language":"nl","provenance":"original_source_reviewed_summary","source_url":"https://openlibrary.org/works/OL733285W","reviewed_at":"2026-11-03T09:26:38.922+00:00","source_name":"Gecontroleerde boek- en catalogusbronnen","source_type":"official_catalog","review_batch"