9789023408192","evidence_url":"https://data.bibliotheken.nl/id/nbt/p822785129","review_batch":"nl-scale-20261102-047","review_status":"approved","bound_language":"dut","card_cover_url":null,"bound_author_id":987346001}'::jsonb as exact union all select 'catalog_work_descriptions:31' as ref,(select to_jsonb(t) from public.catalog_work_descriptions t where t.work_id=987146013 and t.language='nl')='{"text":"Persephone probeert in Nieuw-Athene als gewone journalist te leven. Haar titel als lentegodin voelt onterecht, omdat bloemen onder haar handen juist verdorren. Een kaartspel met een onbekende man brengt haar tegenover Hades, die in de mensenwereld een gokimperium heeft opgebouwd. Hun overeenkomst verplicht haar leven te laten ontstaan in de onderwereld, op straffe van verlies van haar vrijheid. Terwijl zij naar een uitweg zoekt, ontstaat een aantrekkingskracht die de grenzen tussen haar opdracht en haar eigen verlangens minder duidelijk maakt.","work_id":987146013,"evidence":[{"note":"Retain existing Work3280 A Touch of Darkness / Scarlett St. Clair and exact Dutch A Touch of Darkness 9789020550634 Hardcover. KB original-title/volume and existing source-edition parent compared; original content review content-review-025.json retained. No abridgment, omnibus or translated-title duplication established for this selected edition. This changes presentation metadata/summary only; do not claim additionalDutchavailability. Actualhostedfirstcover15144652rejectedasdesktopstudy screenshot. Exactsameedition secondcover15127990 comparedwithprimaryDutchHardback9789020550634, visuallyread and SHA256/70,110B verified. No Work/language/ISBN change.","type":"reviewed_identity_and_bibliography","sources":["http://data.bibliotheken.nl/id/nbt/p438446089"],"reference":"work:3280","checked_at":"2026-11-03T09:26:38.922Z","canonical_name_resolution":null},{"type":"original_substantive_source_review","review":"content-review-025.json","sources":["https://www.zomerenkeuning.nl/boek/a-touch-o